/** The SCL default namespace the generated files declare. */
export const SCL_NS = 'http://www.iec.ch/61850/2003/SCL'

/** The sizes of the files generated by default, in MB. */
export const DEFAULT_SIZES_MB = [5, 10, 50, 100, 200, 500]

/** The buffer written to the stream at once: 8 MB. */
export const FLUSH_AT = 8 * 1024 * 1024
